import 'dart:async';
import 'package:flutter/material.dart';
import 'package:usage_stats/usage_stats.dart';
const bg=Color(0xFF090D0E),card=Color(0xFF121A1C),accent=Color(0xFF00E676),muted=Color(0xFF8A9698);
