class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Ma Timer',debugShowCheckedModeBanner:false,theme:ThemeData(brightness:Brightness.dark,scaffoldBackgroundColor:bg,useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:accent,brightness:Brightness.dark)),home:const Shell());}
class Shell extends StatefulWidget{const Shell({super.key});@override State<Shell> createState()=>_ShellState();}
class _ShellState extends State<Shell>{int tab=0;@override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_){try{UsageStats.grantUsagePermission();}catch(_){}});}@override Widget build(BuildContext c){const pages=[Home(),Apps(),TimerPage(),Trend(),More()];return Scaffold(body:pages[tab],bottomNavigationBar:NavigationBar(backgroundColor:const Color(0xFF0C1112),selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.apps_outlined),label:'Apps'),NavigationDestination(icon:Icon(Icons.timer_outlined),label:'Timer'),NavigationDestination(icon:Icon(Icons.insights_outlined),label:'Trend'),NavigationDestination(icon:Icon(Icons.more_horiz),label:'More')]));}}
class Frame extends StatelessWidget{final Widget child;const Frame({super.key,required this.child});@override Widget build(BuildContext c)=>SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(16),child:child));}
class Header extends StatelessWidget{const Header({super.key});@override Widget build(BuildContext c)=>Row(children:[const Text('Ma Timer',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const Spacer(),IconButton(onPressed:(){},icon:const Icon(Icons.workspace_premium,color:accent)),IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const SettingsPage())),icon:const Icon(Icons.settings_outlined))]);}
