class Stat extends StatelessWidget{final String a,b,c;final double? p;const Stat(this.a,this.b,this.c,{this.p,super.key});@override Widget build(BuildContext x)=>Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:card,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a,style:const TextStyle(color:muted)),const SizedBox(height:6),Row(children:[Text(b,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const Spacer(),Text(c,style:const TextStyle(color:accent))]),if(p!=null)...[const SizedBox(height:10),LinearProgressIndicator(value:p,color:accent)]]));}
