class Home extends StatelessWidget{const Home({super.key});@override Widget build(BuildContext c)=>Frame(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Header(),const SizedBox(height:14),const Notice(),const SizedBox(height:16),Row(children:[const Expanded(child:Stat('Today','4h 32m','↑ 12%')),const SizedBox(width:10),const Expanded(child:Stat('Unlocks','78','↑ 18%'))]),const SizedBox(height:10),const Stat('Target','3h 0m','',p:.72),const SizedBox(height:20),const Text('Top Apps',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...rows()]));}
