class TimerPage extends StatefulWidget{const TimerPage({super.key});@override State<TimerPage> createState()=>_TimerState();}
class _TimerState extends State<TimerPage>{int total=1500,left=1500;Timer? timer;bool running=false;void pick(int m){timer?.cancel();setState((){total=m*60;left=total;running=false;});}void toggle(){if(running){timer?.cancel();setState(()=>running=false);}else{setState(()=>running=true);timer=Timer.periodic(const Duration(seconds:1),(_){if(left==0){timer?.cancel();setState(()=>running=false);}else setState(()=>left--);});}}@override void dispose(){timer?.cancel();super.dispose();}@override Widget build(BuildContext c){final mm=(left/60).floor().toString().padLeft(2,'0'),ss=(left%60).toString().padLeft(2,'0');return Frame(child:Column(children:[const Align(alignment:Alignment.centerLeft,child:Text('Focus Timer',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900))),const SizedBox(height:24),SizedBox(width:260,height:260,child:Stack(alignment:Alignment.center,children:[SizedBox(width:245,height:245,child:CircularProgressIndicator(value:total==left ? .04 : 1-left/total,strokeWidth:12,color:accent,backgroundColor:const Color(0xFF283537))),Text(mm+':'+ss,style:const TextStyle(fontSize:42,fontWeight:FontWeight.w900))])),const Text('Focus Time',style:TextStyle(color:muted)),const SizedBox(height:28),SizedBox(width:double.infinity,height:56,child:FilledButton.icon(onPressed:toggle,icon:Icon(running?Icons.pause:Icons.play_arrow),label:Text(running?'Pause':'Start'),style:FilledButton.styleFrom(backgroundColor:accent,foregroundColor:Colors.black))),const SizedBox(height:14),Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>pick(25),child:const Text('25 min')),OutlinedButton(onPressed:()=>pick(45),child:const Text('45 min')),OutlinedButton(onPressed:()=>pick(60),child:const Text('60 min')),OutlinedButton(onPressed:()=>pick(30),child:const Text('⚙ Custom'))]) ]));}}
class Trend extends StatelessWidget{const Trend({super.key});@override Widget build(BuildContext c)=>Frame(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Trend',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:18),const Text('4h 32m',style:TextStyle(fontSize:34,fontWeight:FontWeight.w900)),const Text('↑ 12% than yesterday',style:TextStyle(color:accent)),const SizedBox(height:20),Container(height:260,padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:card,borderRadius:BorderRadius.circular(18)),child:const Chart()),const SizedBox(height:16),const Card(color:card,child:ListTile(leading:Icon(Icons.lightbulb_outline,color:accent),title:Text('Less phone, more life. You can do better!')))]));}
class Chart extends StatelessWidget{const Chart({super.key});@override Widget build(BuildContext c){const v=[.5,.7,.4,.85,.6,.9,.75],d=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return Row(crossAxisAlignment:CrossAxisAlignment.end,children:[for(int i=0;i<7;i++)Expanded(child:Column(children:[Expanded(child:Align(alignment:Alignment.bottomCenter,child:FractionallySizedBox(heightFactor:v[i],widthFactor:.42,child:DecoratedBox(decoration:BoxDecoration(color:accent,borderRadius:BorderRadius.circular(7)))))),Text(d[i],style:const TextStyle(fontSize:11,color:muted))]))]);}}
